-- Per-tenant retention policies (RETAIN-001, CONTEXT_PACK §7, §8.6, §8.8). Generated by `pnpm db:generate --name
-- retention_policies` from src/schema/retention.ts, then reviewed. Forward-only: never edit once applied.
CREATE TABLE "retention_policies" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"data_class" text NOT NULL,
	"retention_days" integer NOT NULL,
	"min_retention_days" integer NOT NULL,
	"legal_hold_overrides" boolean DEFAULT false NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "retention_policies_tenant_data_class_key" UNIQUE("tenant_id","data_class"),
	CONSTRAINT "retention_policies_data_class_check" CHECK ("retention_policies"."data_class" IN ('findings', 'evidence', 'logs', 'transcripts', 'reports', 'oob_interactions')),
	CONSTRAINT "retention_policies_min_check" CHECK ("retention_policies"."min_retention_days" >= 1),
	CONSTRAINT "retention_policies_days_check" CHECK ("retention_policies"."retention_days" BETWEEN "retention_policies"."min_retention_days" AND 3650),
	CONSTRAINT "retention_policies_legal_hold_check" CHECK ("retention_policies"."legal_hold_overrides" = false)
);
--> statement-breakpoint
ALTER TABLE "retention_policies" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "retention_policies_tenant_isolation" ON "retention_policies" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

--> statement-breakpoint
-- Hand-written (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "retention_policies" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role reads, adds and updates policies. There is no DELETE: a policy is changed, never removed, so the
-- change history in the audit ledger stays complete. Revoke PUBLIC explicitly, as the other tenant tables do.
REVOKE ALL ON "retention_policies" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "retention_policies" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "retention_policies" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with policy changes (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER retention_policies_set_updated_at BEFORE UPDATE ON "retention_policies" FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
